+
+function replaceActiveValues(
+  storage: AccountV2Storage,
+  values: LocalProfileArchiveV1['values'],
+): void {
+  for (const key of ACCOUNT_BOUNDARY_PROFILE_KEYS) {
+    const value = values[key];
