+
+export { ENGINE_VERSION } from '@zodiacs/engine/internal/math';
+
+export type BodyName =
+  | 'Sun' | 'Moon' | 'Mercury' | 'Venus' | 'Mars'
+  | 'Jupiter' | 'Saturn' | 'Uranus' | 'Neptune' | 'Pluto'
+  | 'North Node' | 'South Node';
+
