+  const m = name.match(/GMT([+-])?(\d{1,2})?(?::(\d{2}))?(?::(\d{2}))?/);
+  if (!m) return 0;
+  const sign = m[1] === '-' ? -1 : 1;
+  const h = Number(m[2] ?? 0);
+  const min = Number(m[3] ?? 0);
+  const s = Number(m[4] ?? 0);
+  return sign * (h * 60 + min + s / 60);
+}
