+function wallStringAt(tz: string, utcMs: number): string {
+  const parts = wallFormatter(tz).formatToParts(utcMs);
+  const part = (type: Intl.DateTimeFormatPartTypes): string =>
+    parts.find((candidate) => candidate.type === type)?.value ?? '';
